      "ar": "فَأَمَّا الَّذِينَ ءَامَنُواْ بِاللَّهِ وَاعْتَصَمُواْ بِهِ فَسَيُدْخِلُهُمْ فِي رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا",
      "translit": "Faʾammā lladhīna āmanū billāhi waʿtaṣamū bihī fasayudkhiluhum fī raḥmatin minhu wafaḍlin wayahdīhim ilayhi ṣirāṭan mustaqīmā",
